'use strict';
/* The Motor Trade — monthly retail Deal Day and management meetings.
 * A 'month' is the game's 30-day accounting period, not a calendar month.
 * Incentives apply only to retail consumers/private sellers, never auctions.
 */
(() => {
  const PHASES=Object.freeze([
    {time:'09:00',name:'MORNING ENQUIRIES',detail:'Private sellers arrive and retail buyers begin comparing stock.'},
    {time:'11:00',name:'NEW CUSTOMER LEADS',detail:'A fresh group of owners arrive looking for quick agreements.'},
    {time:'13:00',name:'LUNCHTIME NEGOTIATIONS',detail:'Time-sensitive retail and part-exchange enquiries continue.'},
    {time:'15:00',name:'AFTERNOON PUSH',detail:'Motivated sellers reconsider their prices; retail buyers are more decisive.'},
    {time:'17:00',name:'FINAL HOUR',detail:'Last chance to complete customer transactions before the month closes.'}
  ]);
  const FOCI=Object.freeze({
    sales:{label:'Improve retail conversions',description:'Customer offers improve modestly when negotiating listed stock.'},
    buying:{label:'Protect buying margins',description:'The purchasing team works harder to secure a better direct-seller deal.'},
    care:{label:'Prioritise customer care',description:'Good-condition, fairly priced sales earn an extra point of customer trust.'}
  });
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const monthOf=day=>Math.floor((day-1)/30)+1;
  const isDealDay=day=>day%30===0;
  const isMeetingDay=day=>(day-1)%30===0;
  const initial=()=>({deadlineSession:0,meetingHeldMonth:0,meetingFocus:'steady',meetings:[]});
  const meetingDue=state=>isMeetingDay(state.day)&&state.meetingHeldMonth!==monthOf(state.day);
  const meetingBlocksContinue=state=>state.day>1&&meetingDue(state);
  function dealSession(state){
    return isDealDay(state.day)?PHASES[clamp(state.deadlineSession,0,4)]:null;
  }
  function advanceSession(state){
    if(!isDealDay(state.day))return {ok:false,message:'Today is not the final trading day.'};
    if(state.deadlineSession>=PHASES.length-1)
      return {ok:false,closing:true,message:'Final hour complete. Close the month to see your results.'};
    state.deadlineSession++;
    // Buyers and private sellers refresh between sessions; unresolved
    // enquiries expire. Paid inspections are never refunded.
    for(const vehicle of state.vehicles){
      if(vehicle.status==='listed')vehicle.cashOffer=null;
    }
    state.negotiations={};
    state.reports={};
    const count=leadCount(state.day,state.monthPlan?.startingReputation??state.reputationScore,
      state.deadlineSession,state.name);
    return {ok:true,changed:true,closing:false,
      message:'Deal Day '+PHASES[state.deadlineSession].time+
      ': '+(count===0?'No new private-seller leads this session.':
        count+' private seller '+(count===1?'enquiry':'enquiries')+' arrived.')+
      ' Auction houses remain closed.'};
  }
  // Each operating month has a seeded climate that stays fixed across
  // refreshes, saves, and trading sessions. This is a fictional variability
  // model, not a claim about actual seasonal UK car-market data.
  const CLIMATES=Object.freeze({
    quiet:Object.freeze({label:'QUIET MONTH',description:'Low footfall. Some sessions may have no customer enquiries.',
      arrival:[75,95,100],interest:24,motivation:8,partEx:30,privateChance:10}),
    subdued:Object.freeze({label:'SLOW TRADING',description:'A few enquiries, with owners and buyers generally cautious.',
      arrival:[48,85,100],interest:38,motivation:15,partEx:45,privateChance:18}),
    steady:Object.freeze({label:'STEADY TRADING',description:'Normal footfall. Some sellers may want to complete quickly.',
      arrival:[23,72,95,100],interest:58,motivation:28,partEx:60,privateChance:30}),
    busy:Object.freeze({label:'BUSY MONTH END',description:'More enquiries and potential quick deals, but not all customers will negotiate.',
      arrival:[9,40,80,100],interest:77,motivation:44,partEx:76,privateChance:48}),
    exceptional:Object.freeze({label:'VERY BUSY MONTH END',description:'Unusually high customer interest. Good opportunities are possible, not guaranteed.',
      arrival:[2,12,51,84,100],interest:90,motivation:57,partEx:85,privateChance:63})
  });
  function mix(input){
    // FNV-1a with an avalanche pass; changes in month/name/phase give
    // a stable, dispersed but non-predictably varying simulated market.
    let h=2166136261;
    for(const letter of String(input))h=Math.imul(h^letter.charCodeAt(0),16777619)>>>0;
    h=Math.imul(h^(h>>>15),2246822507)>>>0;
    h=Math.imul(h^(h>>>13),3266489909)>>>0;
    return (h^(h>>>16))>>>0;
  }
  const chance=(key,percent)=>mix(key)%100<percent;
  function conditions(day,name=''){
    const month=monthOf(day);
    const roll=mix('monthly-climate|'+String(name).toLowerCase()+'|'+month)%100;
    const type=roll<24?'quiet':roll<43?'subdued':
      roll<75?'steady':roll<95?'busy':'exceptional';
    return {month,type,...CLIMATES[type]};
  }
  const outlook=state=>conditions(state.day,state.name);
  function leadCount(day,reputation,phase,name=''){
    if(!isDealDay(day))return 0;
    const c=conditions(day,name);
    const roll=mix('visitors|'+name+'|'+monthOf(day)+'|'+phase)%100;
    const picked=c.arrival.findIndex(limit=>roll<limit);
    const extra=(reputation>=40&&chance('trusted|'+name+'|'+day+'|'+phase,28))?1:0;
    return clamp(picked+extra,0,5);
  }
  function customers(day,reputation,phase,templates,profile,name=''){
    if(!isDealDay(day))return null;
    const count=leadCount(day,reputation,phase,name);
    const result=Array.from({length:count},(_,i)=>{
      const key='lead|'+name+'|'+day+'|'+phase+'|'+i;
      const base=templates[mix(key+'|template')%templates.length];
      const adjustment=25*((mix(key+'|ask')%21)-10);
      const ask=Math.max(750,base.ask+adjustment);
      const delta=ask-base.ask;
      const miles=Math.max(3000,base.miles+((mix(key+'|miles')%105)-52)*100);
      const id='S-'+day+'-'+(10+phase*10+i);
      const wantsQuickSale=chance('private|'+name+'|'+day+'|'+id,
        conditions(day,name).privateChance);
      return {...base,ask,floor:Math.max(100,base.floor+delta),
        retail:Math.max(1100,base.retail+delta),miles,
        id,day,kind:'seller',
        note:base.note+(wantsQuickSale?
          ' · Owner hopes to complete today but will negotiate.':
          ' · Owner is checking the market and may walk away.')};
    });
    return {auctions:[],sellers:result.map(car=>({...car,profile:profile(car)}))};
  }
  function sellerDiscount(state,id=''){
    if(!isDealDay(state.day))return 0;
    const c=outlook(state),key='private|'+state.name+'|'+state.day+'|'+id;
    if(!chance(key,c.privateChance))return 0;
    return 35+25*(mix(key+'|value')%5)+state.deadlineSession*5;
  }
  function retailActive(state,vehicle){
    if(!isDealDay(state.day))return true;
    const c=outlook(state);
    return chance('retail-footfall|'+state.name+'|'+state.day+'|'+
      state.deadlineSession+'|'+(vehicle.origin||vehicle.id),
      Math.min(96,c.interest+(state.monthPlan?.startingReputation>=40?4:0)));
  }
  function customerBonus(state,vehicle){
    if(!isDealDay(state.day))return 0;
    const c=outlook(state);
    const key='retail-urgency|'+state.name+'|'+state.day+'|'+
      state.deadlineSession+'|'+(vehicle.origin||vehicle.id);
    if(!chance(key,c.motivation))return 0;
    return 40+25*(mix(key+'|value')%5)+state.deadlineSession*5;
  }
  function partExchangeAvailable(state,vehicle){
    if(!isDealDay(state.day))return true;
    const c=outlook(state);
    return chance('px-interest|'+state.name+'|'+state.day+'|'+
      state.deadlineSession+'|'+(vehicle.origin||vehicle.id),c.partEx);
  }
  function partExchangeDiscount(state,vehicle){
    if(!isDealDay(state.day))return 0;
    const c=outlook(state);
    const key='px-urgency|'+state.name+'|'+state.day+'|'+
      state.deadlineSession+'|'+(vehicle.origin||vehicle.id);
    if(!chance(key,c.motivation))return 0;
    return 25+25*(mix(key+'|value')%3)+state.deadlineSession*5;
  }
  function meetingBonus(state,kind){
    if(kind==='sales'&&state.meetingFocus==='sales')return 55;
    if(kind==='buying'&&state.meetingFocus==='buying')return 45;
    return 0;
  }
  function careBonus(state,car,achievedPrice){
    const grade=car.profile?.grade??3;
    const fair=car.profile?.likelySale??achievedPrice;
    return state.meetingFocus==='care'&&grade<=3&&achievedPrice<=fair+250?1:0;
  }
  function holdMeeting(state,focus){
    if(!isMeetingDay(state.day))
      return {ok:false,message:'Monthly management meetings are held on the first day of each operating month.'};
    const month=monthOf(state.day);
    if(state.meetingHeldMonth===month)
      return {ok:false,message:'This month\'s meeting is already complete.'};
    if(!Object.prototype.hasOwnProperty.call(FOCI,focus))
      return {ok:false,message:'Choose a valid management priority.'};
    const previous=state.monthlyReports.at(-1)||null;
    const minute={
      month,day:state.day,focus,
      previousMonth:previous?.month??null,
      sold:previous?.soldUnits??0,
      target:previous?.targetUnits??0,
      grossMargin:previous?.grossMargin??0,
      agedStock:previous?.agedStock??0,
      staffCosts:previous?.staffCosts??0,
      cash:state.cash,
      reputation:state.reputationScore
    };
    state.meetingHeldMonth=month;
    state.meetingFocus=focus;
    state.meetings.push(minute);
    if(state.meetings.length>120)state.meetings.shift();
    return {ok:true,changed:true,message:
      'Month '+month+' management meeting completed. Priority: '+
      FOCI[focus].label+'. Review the new monthly targets and act on your decisions.'};
  }
  function restore(state,saved){
    if(saved.version<6){
      Object.assign(state,initial());
      // A migrated game on month 2+ may hold its new meeting immediately;
      // no fabricated historical minutes or deadlines are inserted.
      return true;
    }
    const p=saved;
    if(!Number.isSafeInteger(p.deadlineSession)||
      p.deadlineSession<0||p.deadlineSession>=PHASES.length||
      (!isDealDay(state.day)&&p.deadlineSession!==0)||
      !Number.isSafeInteger(p.meetingHeldMonth)||p.meetingHeldMonth<0||
      p.meetingHeldMonth>monthOf(state.day)||
      !['steady',...Object.keys(FOCI)].includes(p.meetingFocus)||
      !Array.isArray(p.meetings)||p.meetings.length>120)return false;
    if(!p.meetings.every(m=>m&&typeof m==='object'&&
      Number.isSafeInteger(m.month)&&m.month>=1&&m.month<=monthOf(state.day)&&
      Number.isSafeInteger(m.day)&&m.day>=1&&m.day<=state.day&&
      typeof m.focus==='string'&&Object.hasOwn(FOCI,m.focus)&&
      (m.previousMonth===null||Number.isSafeInteger(m.previousMonth))&&
      ['sold','target','grossMargin','agedStock','staffCosts','cash','reputation'].every(k=>
        Number.isSafeInteger(m[k]))))return false;
    if(p.meetings.length){
      const last=p.meetings.at(-1);
      if(last.month>p.meetingHeldMonth||
        (last.month===p.meetingHeldMonth&&last.focus!==p.meetingFocus))return false;
    }
    Object.assign(state,{
      deadlineSession:p.deadlineSession,meetingHeldMonth:p.meetingHeldMonth,
      meetingFocus:p.meetingFocus,meetings:p.meetings.map(x=>({...x}))
    });
    return true;
  }
  window.MotorTradeEvents=Object.freeze({
    PHASES,FOCI,monthOf,isDealDay,isMeetingDay,initial,meetingDue,
    meetingBlocksContinue,dealSession,advanceSession,customers,
    conditions,outlook,leadCount,retailActive,partExchangeAvailable,
    sellerDiscount,customerBonus,partExchangeDiscount,meetingBonus,
    careBonus,holdMeeting,restore
  });
})();

workshop.js:
'use strict';
/* The Motor Trade v0.8
 * Vehicle preparation requires diagnosis, paid repair work, elapsed game
 * days and a final quality check. Estimates are fictional, not real garage
 * quotations or assurances of roadworthiness.
 */
(() => {
  const P=window.MotorTradePeople;
  const stages=['unassessed','quoted','in-progress','quality-check','ready'];
  const methods=['internal','external'];
  const integer=Number.isSafeInteger;
  const ok=(message,extra={})=>({ok:true,changed:true,message,...extra});
  const fail=(code,message)=>({ok:false,code,message});
  const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
  function hash(t){
    let n=2166136261;
    for(const c of String(t))n=Math.imul(n^c.charCodeAt(0),16777619)>>>0;
    return n>>>0;
  }
  function initial(vehicle){
    const ready=vehicle.status==='prepared'||vehicle.status==='listed';
    return {stage:ready?'ready':'unassessed',
      assessmentFee:0,method:null,repairCost:ready?vehicle.prepSpent:0,
      remainingDays:0,plannedDays:0,partsDelay:0,startedDay:null,
      completedDay:ready?vehicle.acquiredDay:null,
      technicianId:null,reworks:0,paused:false};
  }
  const reservedCost=v=>v.status==='acquired' &&
    !['in-progress','quality-check'].includes(v.workshop?.stage)?v.prepBudget:0;
  function reserved(state,exceptId=null){
    return state.vehicles.reduce((n,v)=>n+(v.id===exceptId?0:reservedCost(v)),0);
  }
  function find(state,id){
    return state.vehicles.find(v=>v.id===id);
  }
  function charge(state,amount,note){
    state.cash-=amount;
    state.ledger.push({day:state.day,delta:-amount,note});
  }
  function assess(state,id){
    const vehicle=find(state,id);
    if(!vehicle)return fail('missing','Vehicle is not in stock.');
    const job=vehicle.workshop;
    if(vehicle.status!=='acquired'||job.stage!=='unassessed')
      return fail('already','Assessment is only available for newly acquired, unassessed stock.');
    const technician=P.active(state,'technician');
    const fee=technician?30:55;
    if(state.cash<reserved(state)+fee)
      return fail('cash','Insufficient unreserved cash for the £'+fee+' assessment. Preparation reserves are protected.');
    charge(state,fee,'Workshop assessment: '+vehicle.title);
    vehicle.cost+=fee; // The diagnostic fee stays in the car's real acquisition basis.
    job.assessmentFee=fee;
    job.stage='quoted';
    const extra=vehicle.profile?.hiddenFault;
    const detail=extra?' Additional repair identified: '+extra.item+' (£'+extra.cost+').':
      ' No further defect identified beyond known work.';
    return ok('Workshop assessment £'+fee+' completed for '+vehicle.title+'.'+detail+
      ' Choose a repair method; neither option is instantaneous.');
  }
  function quote(state,vehicle,method){
    if(!methods.includes(method))return null;
    const tech=method==='internal'?P.availableTechnicians(state)[0]:null;
    const busyBays=state.vehicles.filter(v=>v.workshop?.method==='internal'&&
      ['in-progress','quality-check'].includes(v.workshop.stage)).length;
    if(method==='internal'&&(!tech||busyBays>=(window.MotorTradePremises?.bays(state)??4)))return null;
    const base=vehicle.prepBudget;
    const saving=method==='internal'?P.labourSaving(state,vehicle,tech):0;
    const supplement=method==='external'?Math.round((base*.12+75)/5)*5:0;
    const cost=base-saving+supplement;
    const grade=vehicle.profile?.grade??3;
    const partsDelay=hash(vehicle.origin+'|parts')%3; // Stable 0–2 day delay.
    const effort=clamp(1+Math.ceil(base/340)+(grade>=4?1:0),2,6);
    const efficiency=method==='internal'&&tech.skills.efficiency>=16?1:0;
    const duration=clamp(effort-efficiency+(method==='external'?0:1)+partsDelay,2,9);
    return {method,cost,duration,partsDelay,saving,supplement,
      technicianId:method==='internal'?tech.id:null,
      provider:method==='external'?'Independent external garage':tech.name};
  }
  function start(state,id,method){
    const vehicle=find(state,id);
    if(!vehicle)return fail('missing','Vehicle not found.');
    if(vehicle.status!=='acquired'||vehicle.workshop.stage!=='quoted')
      return fail('stage','Obtain a workshop assessment before booking repairs.');
    const q=quote(state,vehicle,method);
    if(!q)return method==='internal'&&P.activeTeam(state,'technician').length?
      fail('busy','All available technicians are assigned to repair or quality-check jobs. Finish a job or outsource this one.'):
      fail('staff','An available prep technician is required for internal repairs. Use an external garage instead.');
    if(method==='external'&&state.vehicles.filter(v=>v.id!==id&&
       v.workshop?.stage==='in-progress'&&v.workshop.method==='external').length>=2)
      return fail('busy','External garage capacity is full. Try again when a job is completed.');
    if(q.cost>state.cash-reserved(state,id))
      return fail('cash','Insufficient cash for '+q.provider+
        ' (£'+q.cost+'). Money needed for other unprepared stock is protected.');
    charge(state,q.cost,'Workshop repair booking: '+vehicle.title+
      ' ('+q.provider+')');
    Object.assign(vehicle.workshop,{stage:'in-progress',method,
      repairCost:q.cost,remainingDays:q.duration,plannedDays:q.duration,
      partsDelay:q.partsDelay,startedDay:state.day,completedDay:null,
      technicianId:q.technicianId,reworks:0,paused:false});
    return ok(vehicle.title+' booked with '+q.provider+' for £'+q.cost+
      '. Estimated turnaround '+q.duration+' game days'+
      (q.partsDelay?', including '+q.partsDelay+' parts-wait day(s)':'')+
      '. This car cannot be advertised until repairs and quality control finish.');
  }
  function advance(state){
    const events=[];
    for(const v of state.vehicles){
      const job=v.workshop;
      if(!job||job.stage!=='in-progress'||state.day<=job.startedDay)continue;
      if(job.method==='internal'&&!P.isActive(state,
        state.staff.find(s=>s.id===job.technicianId&&s.role==='technician'))){
        job.paused=true;
        events.push(v.title+' repair paused: assigned technician is unavailable.');
        continue;
      }
      job.paused=false;
      job.remainingDays=Math.max(0,job.remainingDays-1);
      if(job.remainingDays===0){
        job.stage='quality-check';
        events.push(v.title+' repairs finished. Complete the final quality check in Workshop.');
      }
    }
    return events;
  }
  function transfer(state,id){
    const v=find(state,id);
    if(!v)return fail('missing','Vehicle not found.');
    const j=v.workshop;
    if(j?.stage!=='in-progress'||j.method!=='internal')
      return fail('stage','Only an active in-house repair can be transferred externally.');
    // The same two-slot limit applies to transfers as to new bookings.
    // Check before debiting the £125 fee or changing the assignment.
    const outside=state.vehicles.filter(x=>x.id!==id&&
      x.workshop?.stage==='in-progress'&&x.workshop.method==='external').length;
    if(outside>=2)
      return fail('busy','Both external garage slots are occupied. Wait for a job to finish before transferring.');
    const chargeAmount=125;
    if(chargeAmount>state.cash-reserved(state))
      return fail('cash','Insufficient cash to transfer repair work to a garage (£125).');
    charge(state,chargeAmount,'Workshop transfer to outside garage: '+v.title);
    j.repairCost+=chargeAmount;
    j.method='external';
    j.technicianId=null;
    j.remainingDays=Math.max(2,j.remainingDays);
    j.plannedDays+=1;
    j.paused=false;
    return ok(v.title+' transferred to an external garage. £125 charged; remaining turnaround '+
      j.remainingDays+' game days.');
  }
  function quality(state,id){
    const v=find(state,id);
    if(!v)return fail('missing','Vehicle not found.');
    const j=v.workshop;
    if(v.status!=='acquired'||j?.stage!=='quality-check')
      return fail('stage','The repair work must finish before a final quality check.');
    const tech=state.staff.find(x=>x.id===j.technicianId);
    const reliability=tech?.skills.reliability??11;
    const risk=(v.profile?.grade>=4?25:14)-(j.method==='internal'?Math.max(0,reliability-12):0);
    const reworkNeeded=j.reworks===0 && hash('quality|'+v.origin)%100<risk;
    if(reworkNeeded){
      const cost=95+(hash(v.origin+'|rectification')%4)*25;
      if(state.cash<cost+reserved(state))
        return fail('cash','Quality control found additional work costing £'+cost+
          '. Deposit more available cash before authorising rectification.');
      charge(state,cost,'Workshop quality rectification: '+v.title);
      j.repairCost+=cost;
      j.stage='in-progress';
      j.reworks=1;
      j.remainingDays=1;
      j.plannedDays+=1;
      j.startedDay=state.day;
      return ok('Quality check found further work on '+v.title+
        '. £'+cost+' rectification charged and one extra repair day required.');
    }
    j.stage='ready';
    j.completedDay=state.day;
    j.remainingDays=0;
    j.paused=false;
    v.prepSpent=j.repairCost;
    v.status='prepared';
    if(j.method==='internal')P.worked(state,j.technicianId);
    return ok(v.title+' passed final quality control. £'+j.repairCost+
      ' in repair costs recorded. It is now ready to advertise.');
  }
  function valid(vehicle,day,legacy=false){
    const j=vehicle.workshop;
    if(!j||typeof j!=='object'||Array.isArray(j))return false;
    const num=(v,upper=100000)=>integer(v)&&v>=0&&v<=upper;
    if(!stages.includes(j.stage)||!num(j.assessmentFee,200)||
       !num(j.repairCost)||!num(j.remainingDays,12)||!num(j.plannedDays,20)||
       !num(j.partsDelay,3)||!num(j.reworks,1)||
       typeof j.paused!=='boolean'||
       (j.startedDay!==null&&(!num(j.startedDay,36500)||j.startedDay>day))||
       (j.completedDay!==null&&(!num(j.completedDay,36500)||j.completedDay>day))||
       (j.technicianId!==null&&(!num(j.technicianId,100000)||j.technicianId===0))||
       (j.method!==null&&!methods.includes(j.method)))return false;
    if(vehicle.status==='acquired'&&j.stage==='ready')return false;
    if(vehicle.status!=='acquired'&&j.stage!=='ready')return false;
    if(j.stage==='unassessed'&&(j.assessmentFee!==0||j.repairCost!==0||j.method!==null))return false;
    if(j.stage==='quoted'&&(j.assessmentFee===0||j.repairCost!==0||j.method!==null))return false;
    if(['in-progress','quality-check'].includes(j.stage)&&
       (j.assessmentFee===0||!methods.includes(j.method)||j.repairCost<=0||
        j.startedDay===null||j.plannedDays<1))return false;
    if(j.stage==='quality-check'&&j.remainingDays!==0)return false;
    if(j.stage==='ready'&&(vehicle.prepSpent!==j.repairCost||
       j.completedDay===null))return false;
    if(j.stage!=='ready'&&vehicle.prepSpent!==0)return false;
    return true;
  }
  window.MotorTradeWorkshop=Object.freeze({
    initial,reservedCost,reserved,assess,quote,start,advance,transfer,quality,valid
  });
})();

customers.js:
'use strict';
/*
 * The Motor Trade v0.9 — customer journey.
 * Fictional enquiries are reproducible for a vehicle, dealer and game date.
 * Enquiries, appointments, test drives and signed offers are distinct steps.
 * Deposits are held in a separate virtual customer-holding account.
 * At delivery only the remaining customer balance is paid; any deposit is
 * transferred into business cash without double counting. A buyer's change
 * of mind can result in fair retention for actual extra costs recorded by
 * the simulation; dealer fault and legacy refundable terms return all.
 */
(() => {
  const D=window.MotorTradeEvents;
  const P=window.MotorTradePeople;
  if(!P)throw new Error('Load people.js before customers.js');
  const ints=Number.isSafeInteger;
  const STATUS=Object.freeze(['enquiry','booked','arrived','discussing','agreed',
    'reserved','collectable','lost']);
  const FIRST=['Alex','Sam','Jamie','Taylor','Jordan','Morgan','Charlie',
    'Harper','Riley','Casey','Drew','Avery','Robin','Ellis','Frankie'];
  const LAST=['Patel','Jones','Ahmed','Williams','Singh','Brown','Khan',
    'Evans','Wilson','Taylor','Clarke','Morgan','Shah','Davies','Ali'];
  const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
  function hash(text){
    let h=2166136261;
    for(const ch of String(text))h=Math.imul(h^ch.charCodeAt(0),16777619)>>>0;
    h=Math.imul(h^(h>>>15),2246822507)>>>0;
    return (h^(h>>>13))>>>0;
  }
  const chance=(key,percent)=>hash(key)%100<percent;
  const fail=(code,message)=>({ok:false,code,message});
  const ok=(message)=>({ok:true,changed:true,message});
  const caseFor=(state,id)=>state.customerCases?.[String(id)]??null;
  const slot=state=>D.isDealDay(state.day)?state.deadlineSession:0;
  const leadKey=(state,vehicle)=>[
    state.name,state.day,slot(state),vehicle.id,vehicle.origin
  ].join('|');
  const heldDeposits=state=>Object.values(state.customerCases??{})
    .reduce((n,c)=>n+(c.held||0),0);
  function funds(state,c,type,delta){
    (state.customerFunds??=[]).push({day:state.day,vehicleId:c.vehicleId,
      leadId:c.id,type,delta});
    if(state.customerFunds.length>4000)state.customerFunds.shift();
  }
  function customerPrep(state,c){
    // Simulated customer-specific valet, collection inspection, holding
    // paperwork and re-advertising administration: costs actually charged
    // to the business, not a fictitious automatic right to keep a deposit.
    return Math.min(250,75+25*(hash('delivery-work|'+c.id)%8));
  }
  function balanceDue(c){
    return c?Math.max(0,(c.price||0)-(c.allowance||0)-(c.held||0)):0;
  }
  function append(state,caseObj,type,detail=''){
    state.customerHistory.push({day:state.day,vehicleId:caseObj.vehicleId,
      leadId:caseObj.id,type,detail:detail.slice(0,120)});
    if(state.customerHistory.length>2000)state.customerHistory.shift();
  }
  function demand(state,vehicle){
    if(vehicle?.status!=='listed')return false;
    if(caseFor(state,vehicle.id))return false;
    if(D.isDealDay(state.day)&&!D.retailActive(state,vehicle))return false;
    const fair=vehicle.profile?.likelySale||vehicle.retail;
    const overpriced=Math.max(0,(vehicle.asking-fair)/Math.max(fair,1));
    const grade=vehicle.profile?.grade||3;
    let percent=65-Math.round(overpriced*100)-(grade>=4?12:0)+
      Math.floor(state.reputationScore/8)+P.salesImpact(state,vehicle.id).enquiryLift;
    if(D.isDealDay(state.day)){
      const c=D.outlook(state);
      percent+=c.type==='quiet'?-13:c.type==='subdued'?-5:
        c.type==='busy'?9:c.type==='exceptional'?13:0;
    }
    return chance('buyer|'+leadKey(state,vehicle),clamp(percent,8,91));
  }
  function open(state,id){
    const vehicle=state.vehicles.find(v=>v.id===id);
    if(!vehicle||vehicle.status!=='listed')return fail('stock','Advertise a retail-ready vehicle first.');
    if(caseFor(state,id))return fail('existing','This car already has an active customer case.');
    if(!demand(state,vehicle))return fail('no-enquiry','No customer has enquired about this car this session. Try another day or review its price.');
    const key=leadKey(state,vehicle);
    const mode=hash('mode|'+key)%100;
    const preferPX=mode<38&&
      (!D.isDealDay(state.day)||D.partExchangeAvailable(state,vehicle));
    const walkIn=D.isDealDay(state.day);
    const c={
      id:'C-'+state.day+'-'+slot(state)+'-'+vehicle.id+'-'+
        (hash('lead-identity|'+key)%1000000),
      vehicleId:id,createdDay:state.day,createdSession:slot(state),
      name:FIRST[hash('first|'+key)%FIRST.length]+' '+
        LAST[hash('last|'+key)%LAST.length],
      channel:walkIn?'MONTH-END WALK-IN':(hash('channel|'+key)%2?'ONLINE':'TELEPHONE'),
      status:walkIn?'arrived':'enquiry',preferredMode:preferPX?'part-ex':'cash',
      appointmentDay:null,agreedDay:null,price:null,allowance:null,
      collectionDay:null,held:0,counters:0,reason:'',
      terms:'in-person',prepCost:0,exchange:null,
      salespersonId:P.salesRep(state,id)?.id??null
    };
    state.customerCases[String(id)]=c;
    vehicle.cashOffer=null;
    append(state,c,'enquiry',c.channel);
    return ok(c.name+' contacted the dealership about '+vehicle.title+
      (walkIn?'. The customer is here now for a viewing.':
        '. Book a viewing before proceeding to a test drive.'));
  }
  function book(state,id){
    const c=caseFor(state,id);
    if(!c||c.status!=='enquiry')return fail('stage','A new enquiry is required to book a viewing.');
    // A normal viewing must take place within 48 game-hours.
    c.appointmentDay=state.day+1+
      (P.salesImpact(state,c).fastViewing?0:hash('appointment|'+c.id)%2);
    c.status='booked';
    append(state,c,'appointment','Day '+c.appointmentDay);
    return ok(c.name+' has booked a viewing for day '+c.appointmentDay+
      ' (within 48 game-hours). No deposit was paid: the vehicle stays advertised and available to other buyers.');
  }
  function competingInterest(state,id){
    const c=caseFor(state,id),vehicle=state.vehicles.find(v=>v.id===id);
    if(!vehicle||vehicle.status!=='listed'||!c||c.status!=='booked'||
      c.held||c.standby||state.day>=c.appointmentDay||D.isDealDay(state.day))
      return false;
    const fair=vehicle.profile?.likelySale||vehicle.retail;
    const overpriced=Math.max(0,(vehicle.asking-fair)/Math.max(fair,1));
    const percent=clamp(58-Math.round(overpriced*90)-
      (vehicle.profile?.grade>=4?9:0)+Math.floor(state.reputationScore/10)+
      Math.floor(P.salesImpact(state,id).enquiryLift/2),12,88);
    // Stable within the same game day: repeated clicks cannot reroll demand.
    return chance('other-buyer|'+state.name+'|'+state.day+'|'+id+'|'+c.id,percent);
  }
  function attendBooked(state,c,notices){
    if(state.day<c.appointmentDay)return;
    // A short-notice viewing is a much stronger indicator of intent.
    const turnsUp=chance('show|'+c.id,clamp(96+Math.floor(state.reputationScore/15)+
      P.salesImpact(state,c).arrivalLift,90,99));
    if(turnsUp){
      c.status='arrived';
      append(state,c,'arrived','Attended appointment within 48 game-hours');
      if(notices)notices.push(c.name+' arrived for the viewing of stock '+c.vehicleId+'.');
    }else{
      const detail=failCase(state,c,'no-show','Customer failed to attend their appointment.');
      if(notices)notices.push(detail);
    }
  }
  function restoreBooked(state,c,notices){
    if(!c.standby)return false;
    const booked={...c.standby,standby:null};
    state.customerCases[String(c.vehicleId)]=booked;
    // A rival's negotiated offer must not carry into the original buyer's price.
    const vehicle=state.vehicles.find(v=>v.id===c.vehicleId);
    if(vehicle)vehicle.cashOffer=null;
    append(state,booked,'appointment-restored','Competing buyer did not purchase; viewing still booked.');
    attendBooked(state,booked,notices);
    return true;
  }
  function serveCompeting(state,id){
    const booked=caseFor(state,id),vehicle=state.vehicles.find(v=>v.id===id);
    if(!booked||booked.status!=='booked'||!vehicle||vehicle.status!=='listed')
      return fail('stage','A live, unsecured appointment is required for another viewing.');
    if(!competingInterest(state,id))
      return fail('no-enquiry','There is no second buyer available for this car at the moment.');
    const key='other-buyer|'+state.name+'|'+state.day+'|'+id+'|'+booked.id;
    const mode=hash('mode|'+key)%100;
    const c={
      id:'C-'+state.day+'-'+slot(state)+'-'+id+'-'+(hash('identity|'+key)%1000000),
      vehicleId:id,createdDay:state.day,createdSession:slot(state),
      name:FIRST[hash('first|'+key)%FIRST.length]+' '+
        LAST[hash('last|'+key)%LAST.length],
      channel:'WALK-IN',status:'arrived',
      preferredMode:mode<38?'part-ex':'cash',
      appointmentDay:null,agreedDay:null,price:null,allowance:null,
      collectionDay:null,held:0,counters:0,reason:'',
      terms:'in-person',prepCost:0,exchange:null,
      salespersonId:P.salesRep(state,id+1)?.id??null,
      standby:{...booked,standby:null}
    };
    state.customerCases[String(id)]=c;
    vehicle.cashOffer=null;
    append(state,c,'enquiry','Competing walk-in while earlier viewing remained unsecured');
    append(state,c,'arrived','Customer on site for immediate viewing');
    return ok(c.name+' is here to view stock '+id+' now. The original appointment remains booked unless this customer pays a deposit or buys the car. Offer a test drive before agreeing a sale.');
  }
  function testDrive(state,id){
    const c=caseFor(state,id);
    const v=state.vehicles.find(x=>x.id===id);
    if(!c||!v||c.status!=='arrived')return fail('stage','The customer must attend a viewing before a test drive.');
    const key='test-drive|'+c.id;
    const grade=v.profile?.grade||3;
    // An attended test drive is a strong buying signal. Condition still matters.
    const pass=chance(key,clamp(91-(grade>=4?15:0)+
      Math.floor(state.reputationScore/12)+P.salesImpact(state,c).driveLift,65,98));
    append(state,c,pass?'test-drive-pass':'test-drive-reject',
      pass?'Customer wants to discuss terms':'Customer did not proceed');
    if(!pass){
      c.status='lost';
      c.reason='Customer did not like the condition or driving experience.';
      restoreBooked(state,c);
      return {ok:false,changed:true,code:'drive-rejected',
        message:c.name+' declined to proceed after the test drive. No sale was made.'};
    }
    c.status='discussing';
    return ok(c.name+' completed a satisfactory test drive. You can now discuss cash or part-exchange terms.');
  }
  function negotiate(state,vehicle,current,limit){
    const c=caseFor(state,vehicle.id);
    if(!c||c.status!=='discussing')return fail('stage','A completed test drive is required before negotiations.');
    if(c.counters>=2)return fail('limit','This customer will not consider another counteroffer.');
    const next=current+150;
    c.counters++;
    if(next>limit){
      append(state,c,'counter-rejected','Beyond customer budget');
      return {ok:false,changed:true,code:'rejected',message:c.name+
        ' cannot increase their offer beyond their budget.'};
    }
    const receptive=chance('counter|'+c.id+'|'+c.counters,
      clamp(82+(state.reputationScore>=40?6:0)-(c.counters-1)*12+
      P.salesImpact(state,c).counterLift,35,96));
    if(!receptive){
      const walk=chance('walk|'+c.id+'|'+c.counters,25);
      append(state,c,'counter-rejected',walk?'Customer walked away':'Customer declined increase');
      if(walk){
        c.status='lost';
        c.reason='Customer walked away after a counteroffer.';
        restoreBooked(state,c);
      }
      return {ok:false,changed:true,code:walk?'walked':'rejected',
        message:c.name+(walk?' walked away after the higher counteroffer.':
          ' declined the increase. Their last offer remains available.')};
    }
    vehicle.cashOffer=next;
    append(state,c,'counter-accepted','Increase of £150');
    return ok(c.name+' has agreed to increase the cash offer to £'+next+'.');
  }
  function agree(state,id,mode,price,allowance,exchange){
    const c=caseFor(state,id);
    if(!c||c.status!=='discussing')return fail('stage','The customer must complete a test drive and negotiate first.');
    if(!['cash','part-ex'].includes(mode))return fail('mode','Invalid sale method.');
    if(mode==='part-ex'&&c.preferredMode!=='part-ex')
      return fail('mode','This customer is not offering a part-exchange.');
    if(!ints(price)||price<500||price>100000)return fail('price','Invalid negotiated price.');
    if(mode==='part-ex'&&(!exchange||!ints(allowance)||allowance<exchange.floor||
       allowance>exchange.ask||allowance>=price))
      return fail('allowance','Part-exchange allowance is outside the agreed customer range.');
    Object.assign(c,{status:'agreed',agreedDay:state.day,
      price,allowance:mode==='part-ex'?allowance:0,
      exchange:mode==='part-ex'?{...exchange}:null,preferredMode:mode});
    append(state,c,'agreement',mode);
    return ok('Agreement reached with '+c.name+' for £'+price+
      (mode==='part-ex'?' including a £'+allowance+' part-exchange allowance.':'.')+
      ' Complete handover today or take a £250 reservation deposit under clear cancellation terms for later collection.');
  }
  function deposit(state,id){
    const c=caseFor(state,id);
    if(!c||c.status!=='agreed')return fail('stage','Agree the sale before taking a reservation deposit.');
    const expense=customerPrep(state,c);
    const reserved=window.MotorTradeWorkshop?.reserved(state)??0;
    if(state.cash-expense<reserved)
      return fail('cash','Insufficient unreserved dealership cash for the '+expense+
        ' customer-specific collection preparation cost. Do not accept a reservation you cannot service.');
    // The customer pays £250 into a virtual segregated account; that money
    // is not spendable business cash and is not a vehicle sale.
    c.held=250;
    c.terms='in-person';
    c.prepCost=expense;
    c.collectionDay=state.day+1+(hash('collection|'+c.id)%2);
    if(c.standby){
      append(state,c.standby,'appointment-displaced',
        'Car secured by another buyer paying a deposit; no deposit on original viewing.');
      c.standby=null;
    }
    c.status='reserved';
    funds(state,c,'received',250);
    state.cash-=expense;
    state.ledger.push({day:state.day,delta:-expense,
      note:'Customer-specific collection preparation: '+c.name+' / stock '+id});
    append(state,c,'deposit','£250 received into separate holding; customer-specific work £'+expense);
    return ok('£250 deposit taken and held separately for '+c.name+
      '. Collection day '+c.collectionDay+'. Customer owes '+balanceDue(c)+
      ' at handover. You paid £'+expense+' in customer-specific preparation. '+
      'If the customer withdraws, retention is limited to demonstrable direct costs; dealer-fault cancellations receive a full refund.');
  }
  function settle(state,c,reason='buyer'){
    const held=c.held||0;
    if(!held)return {retained:0,refunded:0};
    // Old v0.9 customers agreed to unconditional refunds; honour them.
    const retained=reason==='buyer'&&c.terms==='in-person'?
      Math.min(held,c.prepCost||0):0;
    const refunded=held-retained;
    if(refunded)funds(state,c,'refunded',-refunded);
    if(retained){
      funds(state,c,'retained',-retained);
      state.cash+=retained;
      state.ledger.push({day:state.day,delta:retained,
        note:'Fair cancellation cost recovery: '+c.name+' / stock '+c.vehicleId});
    }
    c.held=0;
    return {retained,refunded};
  }
  function cancel(state,id,reason='buyer'){
    const c=caseFor(state,id);
    if(!c||!['enquiry','booked','arrived','discussing','agreed','reserved','collectable'].includes(c.status))
      return fail('stage','No open customer arrangement can be cancelled.');
    if(!['buyer','dealer'].includes(reason))return fail('reason','Invalid cancellation reason.');
    const amounts=settle(state,c,reason);
    c.status='lost';
    c.reason=reason==='buyer'?'Customer withdrew from the purchase.':
      'Dealership cancelled and refunded all remaining customer funds.';
    append(state,c,amounts.refunded?'deposit-refunded':'cancelled',
      'Customer deposit: £'+amounts.retained+' retained against recorded costs; £'+
      amounts.refunded+' refunded.');
    if(amounts.retained)append(state,c,'deposit-retained',
      'Direct costs recovered: £'+amounts.retained);
    restoreBooked(state,c);
    return ok(c.reason+(amounts.refunded?' £'+amounts.refunded+' refunded.':'')+
      (amounts.retained?' £'+amounts.retained+' retained against recorded customer-specific costs.':''));
  }
  function ready(state,id){
    const c=caseFor(state,id);
    return c&&['agreed','collectable'].includes(c.status)&&
      (c.status!=='agreed'||c.agreedDay===state.day);
  }
  function complete(state,id){
    const c=caseFor(state,id);
    if(!ready(state,id))return fail('stage','A test drive, agreed terms and an eligible handover are required.');
    const appliedDeposit=c.held||0;
    if(appliedDeposit){
      funds(state,c,'applied',-appliedDeposit);
      c.held=0;
    }
    append(state,c,'sale',c.preferredMode);
    if(c.standby)append(state,c.standby,'appointment-displaced',
      'Car sold to competing buyer before original unsecured appointment.');
    delete state.customerCases[String(id)];
    return {ok:true,changed:true,appliedDeposit,message:appliedDeposit?
      'Deposit transferred from holding account; balance paid at handover.':
      'Customer collected the vehicle and the sale completed.'};
  }
  function failCase(state,c,type,reason){
    const money=settle(state,c,'buyer');
    c.status='lost';
    c.reason=reason;
    append(state,c,type==='deposit-refunded'?'cancelled':type,reason);
    if(money.refunded)append(state,c,'deposit-refunded','£'+money.refunded+' returned');
    if(money.retained)append(state,c,'deposit-retained','£'+money.retained+' direct costs recovered');
    return reason+(money.retained?' £'+money.retained+' of the deposit retained against costs.':'')+
      (money.refunded?' £'+money.refunded+' refunded.':'');
  }
  function advanceDay(state){
    const notices=[];
    for(const c of Object.values(state.customerCases)){
      if(c.status==='lost'){
        if(!restoreBooked(state,c,notices)&&c.createdDay<state.day)
          delete state.customerCases[String(c.vehicleId)];
        continue;
      }
      if(c.status==='booked'&&state.day>=c.appointmentDay){
        attendBooked(state,c,notices);
      }else if(c.status==='reserved'&&state.day>=c.collectionDay){
        // A paid deposit is a genuine reservation, so no competing buyers.
        if(chance('collect|'+c.id,96)){
          c.status='collectable';
          append(state,c,'collection-due','Customer ready to collect');
          notices.push(c.name+' is ready to collect stock '+c.vehicleId+'.');
        }else{
          notices.push(failCase(state,c,'deposit-refunded','Customer cancelled before collection.'));
        }
      }else if(c.status==='collectable'&&state.day>c.collectionDay+5){
        notices.push(failCase(state,c,'deposit-refunded',
          'Customer withdrew after the collection grace period passed.'));
      }else if(['enquiry','arrived','discussing','agreed'].includes(c.status)&&
        c.createdDay<state.day){
        notices.push(failCase(state,c,'expired','Customer enquiry expired without a completed agreement.'));
        restoreBooked(state,c,notices);
      }
    }
    return notices;
  }
  function nextSession(state){
    for(const c of Object.values(state.customerCases)){
      if(['reserved','collectable'].includes(c.status))continue;
      if(c.status==='lost'){
        delete state.customerCases[String(c.vehicleId)];
        continue;
      }
      if(c.createdDay!==state.day||c.createdSession===state.deadlineSession)continue;
      failCase(state,c,'expired','Customer left as the next Deal Day session began.');
      delete state.customerCases[String(c.vehicleId)];
    }
  }
  function stats(state,startDay,endDay){
    const events=state.customerHistory.filter(x=>x.day>=startDay&&x.day<=endDay);
    const n=type=>events.filter(e=>e.type===type).length;
    return {enquiries:n('enquiry'),appointments:n('appointment'),
      attended:n('arrived'),noShows:n('no-show'),
      testDrives:n('test-drive-pass')+n('test-drive-reject'),
      declinedTestDrives:n('test-drive-reject'),
      agreements:n('agreement'),deposits:n('deposit'),
      refunds:n('deposit-refunded'),retainedDeposits:n('deposit-retained'),
      retainedAmount:state.customerFunds?.filter(x=>x.type==='retained'&&
        x.day>=startDay&&x.day<=endDay).reduce((n,x)=>n-x.delta,0)||0,
      completedSales:n('sale'),
      counterRejections:n('counter-rejected')};
  }
  function valid(state,saved){
    if(saved.version<8){
      state.customerCases={};state.customerHistory=[];state.customerFunds=[];
      return true;
    }
    const cases=saved.customerCases,history=saved.customerHistory;
    if(!cases||typeof cases!=='object'||Array.isArray(cases)||
      !Array.isArray(history)||history.length>2000||
      Object.keys(cases).length>state.capacity)return false;
    const no=(x,max=100000000)=>ints(x)&&x>=0&&x<=max;
    const validCase=([id,c])=>/^\d+$/.test(id)&&c&&
      c.vehicleId===Number(id)&&state.vehicles.some(v=>v.id===c.vehicleId&&v.status==='listed')&&
      typeof c.id==='string'&&/^C-\d+-\d+-\d+-\d+$/.test(c.id)&&
      typeof c.name==='string'&&c.name.length>=2&&c.name.length<70&&
      typeof c.channel==='string'&&c.channel.length<=30&&
      STATUS.includes(c.status)&&['cash','part-ex'].includes(c.preferredMode)&&
      no(c.createdDay,36500)&&c.createdDay>=1&&c.createdDay<=state.day&&
      no(c.createdSession,4)&&
      (c.salespersonId==null||(ints(c.salespersonId)&&c.salespersonId>0&&
        c.salespersonId<100000))&&
      ['appointmentDay','agreedDay','collectionDay'].every(k=>
        c[k]===null||(no(c[k],36505)&&c[k]>=c.createdDay))&&
      ['price','allowance'].every(k=>c[k]===null||no(c[k]))&&
      no(c.held,250)&&[0,250].includes(c.held)&&
      no(c.counters,2)&&typeof c.reason==='string'&&c.reason.length<200&&
      (c.exchange===null||(c.exchange&&typeof c.exchange==='object'&&
        typeof c.exchange.title==='string'&&no(c.exchange.ask)&&no(c.exchange.floor)))&&
      (!['reserved','collectable'].includes(c.status)||c.held===250)&&
      (!['agreed','reserved','collectable'].includes(c.status)||
        no(c.price)&&c.price>=500)&&
      (c.status!=='lost'||c.held===0)&&
      (!['agreed','reserved','collectable'].includes(c.status)||
        c.price<=state.vehicles.find(v=>v.id===c.vehicleId).asking)&&
      (c.preferredMode!=='part-ex'||!['agreed','reserved','collectable'].includes(c.status)||
        (c.exchange&&c.allowance>=c.exchange.floor&&
          c.allowance<=c.exchange.ask&&c.allowance<c.price))&&
      (!c.standby||(c.standby.standby==null&&c.standby.status==='booked'&&
        c.standby.held===0&&c.standby.vehicleId===c.vehicleId&&
        !['booked','reserved','collectable'].includes(c.status)&&
        validCase([id,c.standby])));
    if(!Object.entries(cases).every(validCase))return false;
    const types=['enquiry','appointment','appointment-restored','appointment-displaced',
      'test-drive-pass','test-drive-reject',
      'counter-accepted','counter-rejected','agreement','deposit','deposit-refunded',
      'deposit-retained','cancelled','arrived','no-show','expired','collection-due','sale'];
    if(!history.every(h=>h&&no(h.day,36500)&&h.day>=1&&h.day<=state.day&&
      no(h.vehicleId,100000)&&h.vehicleId>0&&
      typeof h.leadId==='string'&&h.leadId.length<=50&&
      types.includes(h.type)&&typeof h.detail==='string'&&h.detail.length<=120))
      return false;
    const existingFunds=saved.version>=9?saved.customerFunds:
      Object.values(cases).filter(c=>c.held>0).map(c=>({
        day:c.agreedDay??c.createdDay,vehicleId:c.vehicleId,
        leadId:c.id,type:'received',delta:c.held
      }));
    if(!Array.isArray(existingFunds)||existingFunds.length>4000)return false;
    const typesOfFunds=['received','refunded','retained','applied'];
    if(!existingFunds.every(v=>v&&no(v.day,36500)&&v.day>=1&&v.day<=state.day&&
      no(v.vehicleId,100000)&&v.vehicleId>0&&
      typeof v.leadId==='string'&&v.leadId.length<70&&
      typesOfFunds.includes(v.type)&&ints(v.delta)&&
      (v.type==='received'?v.delta===250:v.delta<0&&v.delta>=-250)))return false;
    if(existingFunds.reduce((n,x)=>n+x.delta,0)!==Object.values(cases)
      .reduce((n,c)=>n+(c.held||0),0))return false;
    if(saved.version>=9&&!Object.values(cases).every(c=>
      ['in-person','legacy-refundable'].includes(c.terms)&&
      no(c.prepCost,250)&&
      (c.held===0||c.terms==='legacy-refundable'||c.prepCost>=75)))return false;
    state.customerCases=Object.fromEntries(Object.entries(cases).map(([key,c])=>
      [key,{...c,terms:saved.version>=9?c.terms:'legacy-refundable',
        prepCost:saved.version>=9?c.prepCost:0,
        exchange:c.exchange?{...c.exchange}:null,
        standby:c.standby?{...c.standby,standby:null}:null}]));
    state.customerHistory=history.map(h=>({...h}));
    state.customerFunds=existingFunds.map(v=>({...v}));
    return true;
  }
  window.MotorTradeCustomers=Object.freeze({
    caseFor,demand,open,book,competingInterest,serveCompeting,testDrive,negotiate,agree,deposit,cancel,
    ready,complete,advanceDay,nextSession,stats,valid,heldDeposits,balanceDue,customerPrep
  });
})();

trading.js:
'use strict';
/*
 * The Motor Trade — deterministic, fictional trading engine.
 * Prices and buyer behaviour are gameplay examples, not live valuations.
 * Gross trading margin is before tax, VAT adjustments and business overheads.
 */
(() => {
  const STARTING_CASH = 12500; // legacy career basis, retained for old saves
  const STAFFED_STARTING_CASH = 45000; // fully salaried new-dealership career
  const CAPACITY = 4;
  const VERSION = 14;
  const PH = window.MotorTradePhotos;
  if(!PH)throw new Error('Load vehicle-photos.js before trading.js');
  const MARKET = window.MotorTradeMarket;
  if(!MARKET)throw new Error('Load vehicle-market.js before trading.js');
  const C = window.MotorTradeCustomers;
  if(!C)throw new Error('Load customers.js before trading.js');
  const W = window.MotorTradeWorkshop;
  if (!W) throw new Error('Load workshop.js before trading.js');
  const D = window.MotorTradeEvents;
  if (!D) throw new Error('Load events.js before trading.js');
  const M = window.MotorTradeMonthly;
  if (!M) throw new Error('Load monthly.js before trading.js');
  const P = window.MotorTradePeople;
  if (!P) throw new Error('Load people.js before trading.js');
  const SITE = window.MotorTradePremises;
  if (!SITE) throw new Error('Load premises.js before trading.js');
  const I = window.MotorTradeIntel;
  if (!I) throw new Error('Load vehicle-intel.js before trading.js');
  const MAX_DAY = 36500;
  // Stock templates are maintained in vehicle-market.js. Never mutate the
  // curated rows: daily price, mileage and identifiers are generated below.
  const integer = value => Number.isSafeInteger(value);
  const cashValue = value => integer(value) && value >= 0 && value <= 100000000;
  const own = (arr, id) => arr.find(v => v.id === id);
  const sum = (items, key) => items.reduce((total, item) => total + item[key], 0);
  // Seeded, stable daily supply: the same career day gives the same listings
  // after reload, while volume, models, valuations and mileage vary across days.
  const sample = (day,index,salt) => {
    let v = ((day * 374761393) ^ (index * 668265263) ^ salt) >>> 0;
    v = Math.imul(v ^ (v >>> 13),1274126177) >>> 0;
    return (v ^ (v >>> 16)) >>> 0;
  };
  const nearest25 = n => Math.round(n / 25) * 25;
  // Game calendar starts Monday 9 November 2026. Normally Monday auction;
  // where Monday is month-end Deal Day, use Tuesday of the SAME game week.
  // This guarantees exactly one weekday auction per week, never weekends.
  function scheduledAuctionDay(day){
    const monday=1+Math.floor((day-1)/7)*7;
    return D.isDealDay(monday)?monday+1:monday;
  }
  const auctionDay=day=>integer(day)&&day>=1&&day===scheduledAuctionDay(day);
  function nextAuctionDay(day){
    const thisWeek=scheduledAuctionDay(day);
    return thisWeek>day?thisWeek:scheduledAuctionDay(day+7);
  }
  function market(day,reputationScore=0,session=0,dealershipName='',
    periodReputation=reputationScore,cash=STARTING_CASH) {
    const tier=MARKET.tierFor(cash,reputationScore).key;
    const dealSellers=MARKET.sellersForDealDay(cash,reputationScore);
    const special=D.customers(day,periodReputation,session,dealSellers,I.profile,dealershipName);
    if(special)return {auctions:[],sellers:special.sellers.map(x=>({...x,...PH.describe(x)}))};
    const auctionCount=auctionDay(day)?
      (day===1?3:3+(sample(day,1,29)%3)):0;
    const baselineSellers=day===1?2:
      (sample(day,0,31)%5===0?0:1+(sample(day,1,37)%3));
    const sellerCount=Math.min(4,baselineSellers+
      (day>1&&reputationScore>=40&&baselineSellers>0?1:0));
    const aCount=auctionCount;
    const usedAuction=new Set(),usedSeller=new Set();
    const starter=MARKET.CATALOGUE.starter;
    const auctions=Array.from({length:aCount},(_,i)=>{
      const base=day===1?starter[i]:MARKET.pick('auction',tier,day,i,usedAuction);
      const offset=day===1?0:nearest25((sample(day,i,91)%851)-425);
      const guide=Math.max(850,base.guide+offset);
      const delta=guide-base.guide;
      const miles=Math.max(3500,base.miles+
        (day===1?0:((sample(day,i,54)%250)-125)*100));
      const fee=base.fee+(day===1?0:25*((sample(day,i,82)%3)-1));
      return {...base,guide,reserve:base.reserve+delta,rival:base.rival+delta,
        retail:base.retail+delta,miles,fee,
        id:'A-'+day+'-'+i,kind:'auction',day};
    });
    const sellers=Array.from({length:sellerCount},(_,i)=>{
      const base=day===1?starter[3+i]:MARKET.pick('seller',tier,day,i,usedSeller);
      const offset=day===1?0:nearest25((sample(day,i,51)%601)-300);
      const ask=Math.max(950,base.ask+offset);
      const delta=ask-base.ask;
      const miles=Math.max(3500,base.miles+
        (day===1?0:((sample(day,i,44)%250)-125)*100));
      return {...base,ask,floor:Math.max(100,base.floor+delta),
        retail:base.retail+delta,miles,
        id:'S-'+day+'-'+i,kind:'seller',day};
    });
    return {
      auctions:auctions.map(car=>({...car,...PH.describe(car),profile:I.profile(car)})),
      sellers:sellers.map(car=>({...car,...PH.describe(car),profile:I.profile(car)}))
    };
  }
  // Daily catalogues must never reroll after a purchase, inspection or sale.
  // Opening cash is reconstructed from the existing ledger, avoiding a new
  // save field and preserving all v1-v9 careers. Reputation access is reviewed
  // at each 30-day management period, not halfway through a trading session.
  function marketStatus(state){
    const todaysMovement=state.ledger.reduce((n,x)=>n+(x.day===state.day?x.delta:0),0);
    const openingCash=state.cash-todaysMovement;
    const periodRep=state.monthPlan?.startingReputation??state.reputationScore;
    return MARKET.progress(openingCash,periodRep);
  }
  const marketFor=state=>{
    const status=marketStatus(state);
    const todaysMovement=state.ledger.reduce((n,x)=>n+(x.day===state.day?x.delta:0),0);
    return market(state.day,state.monthPlan?.startingReputation??state.reputationScore,
      state.deadlineSession,state.name,
      state.monthPlan?.startingReputation??state.reputationScore,
      state.cash-todaysMovement);
  };
  // Weekly live auctions: sequential numbered lots; bids continue until one
  // dealer drops out. When the highest bid meets reserve, the hammer creates
  // a separate invoice that must be paid before workshop transfer.
  const auctionPhases=['catalogue','bidding','payment','result','finished'];
  const auctionKinds=['won','lost','passed','unsold','owned'];
  const auctionIncrements=[100,250,500];
  const initialAuctionHall=day=>({
    day,index:0,phase:'catalogue',currentBid:0,leader:'none',
    playerBid:0,rivalFolded:false,rounds:0,feed:[],results:[]
  });
  const lotNumber=index=>String(index+1).padStart(3,'0');
  function auctionLot(state){
    return marketFor(state).auctions[state.auctionHall.index]||null;
  }
  function auctionValid(state){
    const h=state.auctionHall,history=state.auctionHistory;
    if(!h||typeof h!=='object'||Array.isArray(h)||
       !Array.isArray(history)||history.length>160||
       !integer(h.day)||h.day!==state.day||
       !integer(h.index)||h.index<0||
       !auctionPhases.includes(h.phase)||
       !integer(h.currentBid)||h.currentBid<0||h.currentBid>100000||
       !['none','rival','player'].includes(h.leader)||
       !integer(h.playerBid)||h.playerBid<0||h.playerBid>100000||
       typeof h.rivalFolded!=='boolean'||
       !integer(h.rounds)||h.rounds<0||h.rounds>250||
       !Array.isArray(h.feed)||h.feed.length>65||
       !h.feed.every(entry=>typeof entry==='string'&&entry.length<=160)||
       !Array.isArray(h.results)||h.results.length>20)return false;
    const lots=marketFor(state).auctions;
    if(h.index>lots.length||
       (h.phase==='finished'&&h.index!==lots.length)||
       (h.phase!=='finished'&&h.index>=lots.length&&lots.length>0)||
       (h.phase==='result'&&h.results.length!==h.index+1)||
       (h.phase!=='result'&&h.results.length!==h.index)||
       (h.phase==='catalogue'&&
         (h.currentBid!==0||h.playerBid!==0||h.rounds!==0||h.feed.length>0))||
       (h.phase==='bidding'&&
         (h.currentBid<lots[h.index].guide||h.leader==='none'||h.rounds>250))||
       (h.phase==='payment'&&(!lots[h.index]||h.leader!=='player'||
         !h.rivalFolded||h.currentBid!==h.playerBid||
         h.currentBid<lots[h.index].reserve))||
       (h.phase==='finished'&&h.feed.length>0))return false;
    const validResult=r=>r&&typeof r==='object'&&!Array.isArray(r)&&
      integer(r.day)&&r.day>=1&&r.day<=state.day&&
      /^A-[0-9]+-[0-9]+$/.test(r.lotId)&&
      typeof r.title==='string'&&r.title.length>=2&&r.title.length<100&&
      typeof r.lotNumber==='string'&&/^\d{3}$/.test(r.lotNumber)&&
      auctionKinds.includes(r.kind)&&
      integer(r.hammer)&&r.hammer>=0&&r.hammer<=100000&&
      integer(r.fee)&&r.fee>=0&&r.fee<=5000&&
      (r.kind==='won'?r.hammer>0&&r.fee>0:r.fee===0)&&
      integer(r.total)&&r.total===r.hammer+r.fee&&
      typeof r.detail==='string'&&r.detail.length<=160;
    if(!history.every(validResult)||!h.results.every(validResult))return false;
    if(h.results.some((r,i)=>r.day!==state.day||r.lotId!==lots[i]?.id||
      r.lotNumber!==lotNumber(i)))return false;
    if(h.phase==='bidding'&&h.leader==='player'&&
      h.currentBid>=lots[h.index].reserve)return false;
    const winners=[...history,...h.results].filter(r=>r.kind==='won');
    return winners.every(r=>state.ledger.some(l=>l.day===r.day&&
      l.delta===-r.total&&
      l.note.startsWith('Auction purchase: '+r.title+' (bid '+r.hammer+
        ', buyer fee '+r.fee+')')));
  }
  function resolveAuction(state,kind,hammer,detail){
    const h=state.auctionHall,lot=auctionLot(state);
    const fee=kind==='won'?lot.fee:0;
    const result={day:state.day,lotId:lot.id,
      lotNumber:lotNumber(h.index),title:lot.title,
      kind,hammer,fee,total:hammer+fee,detail};
    h.results.push(result);
    state.auctionHistory.push({...result});
    if(state.auctionHistory.length>160)state.auctionHistory.shift();
    h.phase='result';
    h.feed.push(detail);
    if(h.feed.length>65)h.feed=h.feed.slice(-65);
    return {ok:true,changed:true,message:detail};
  }
  function startAuction(state){
    const h=state.auctionHall;
    if(h.phase!=='catalogue')return fail('stage','Finish the current lot before opening bidding.');
    const lot=auctionLot(state);
    if(!lot)return fail('closed','No auction lots are available in this session.');
    if(state.vehicles.some(v=>v.origin===lot.id)||
       state.sold.some(v=>v.origin===lot.id)||
       state.auctionHistory.some(r=>r.kind==='won'&&r.lotId===lot.id))
      return resolveAuction(state,'owned',0,
        'LOT '+lotNumber(h.index)+' was already purchased before the Auction Hall update. No additional charge.');
    h.phase='bidding';h.currentBid=lot.guide;h.leader='rival';
    h.playerBid=0;h.rivalFolded=false;h.rounds=0;
    h.feed=['LOT '+lotNumber(h.index)+' · '+lot.title+' enters the ring.',
      'Regional dealer opens bidding at £'+lot.guide.toLocaleString('en-GB')+'.'];
    return {ok:true,changed:true,message:'Bidding is open for LOT '+lotNumber(h.index)+
      '. The opening rival bid is £'+lot.guide.toLocaleString('en-GB')+
      '. Bid in increments or walk away.'};
  }
  function bidLiveAuction(state,increment){
    const h=state.auctionHall;
    if(h.phase!=='bidding')return fail('stage','Open this lot for bidding first.');
    if(!auctionIncrements.includes(increment))return fail('bid','Choose a £100, £250 or £500 increment.');
    if(h.leader!=='rival')return fail('stage','Only raise against another dealer. The bidding has already ended.');
    const lot=auctionLot(state);
    if(!lot)return fail('closed','This auction lot is no longer available.');
    const bid=h.currentBid+increment;
    if(bid>100000)return fail('bid','The live bid exceeds the supported auction price.');
    if(state.vehicles.some(v=>v.origin===lot.id))
      return fail('owned','This car has already been bought.');
    const requiredPrep=lot.profile.basePrep+(lot.profile.hiddenFault?.cost||0);
    const blocked=canBuy(state,bid+lot.fee,requiredPrep);
    if(blocked)return blocked;
    const money=n=>'£'+n.toLocaleString('en-GB');
    h.currentBid=bid;h.playerBid=bid;h.leader='player';h.rounds++;
    h.feed.push('YOU bid '+money(bid)+' (+'+money(increment)+').');
    // The competitor never rerolls on repeated actions: its maximum was fixed
    // when the daily market catalogue was generated.
    if(!h.rivalFolded&&bid+100<=lot.rival){
      h.currentBid=bid+100;h.leader='rival';
      h.feed.push('Regional dealer counters at '+money(h.currentBid)+'.');
      if(h.feed.length>65)h.feed=h.feed.slice(-65);
      return {ok:true,changed:true,message:'Rival dealer has outbid you at '+
        money(h.currentBid)+'. Raise your bid or pass. No money has been taken.'};
    }
    h.rivalFolded=true;
    h.feed.push('Regional dealer cannot match '+money(bid)+' and withdraws.');
    if(bid<lot.reserve){
      h.feed.push('Auctioneer: vendor reserve not met — lot remains unsold.');
      return resolveAuction(state,'unsold',0,'LOT '+lotNumber(h.index)+
        ' received no competing bid above '+money(bid)+
        ', but the vendor reserve was not met. No sale or buyer fee.');
    }
    // Hammer is final, but ownership and payment transfer occur only after
    // the separate buyer invoice has been confirmed.
    h.phase='payment';
    h.feed.push('HAMMER DOWN at '+money(bid)+'. Rival is out. Payment required before collection.');
    if(h.feed.length>65)h.feed=h.feed.slice(-65);
    return {ok:true,changed:true,message:'HAMMER FALLEN — LOT '+lotNumber(h.index)+
      ' at '+money(bid)+'. Rival dealer has dropped out. Finalise payment of '+
      money(bid+lot.fee)+' including buyer fee '+money(lot.fee)+
      ' to transfer the car into your workshop.'};
  }
  function settleAuction(state){
    const h=state.auctionHall;
    if(h.phase!=='payment')return fail('stage','There is no outstanding auction invoice.');
    const lot=auctionLot(state);
    if(!lot)return fail('closed','This auction invoice cannot be matched to a lot.');
    if(state.vehicles.some(v=>v.origin===lot.id)||
       state.auctionHistory.some(r=>r.kind==='won'&&r.lotId===lot.id))
      return fail('owned','This lot has already been settled. No second payment is permitted.');
    const requiredPrep=lot.profile.basePrep+(lot.profile.hiddenFault?.cost||0);
    const blocked=canBuy(state,h.currentBid+lot.fee,requiredPrep);
    if(blocked)return blocked;
    const hammer=h.currentBid;
    pay(state,-(hammer+lot.fee),'Auction purchase: '+lot.title+
      ' (bid '+hammer+', buyer fee '+lot.fee+')');
    addCar(state,lot,'auction',hammer+lot.fee,lot.id);
    h.feed.push('SETTLED. £'+hammer.toLocaleString('en-GB')+
      ' hammer plus £'+lot.fee.toLocaleString('en-GB')+
      ' buyer fee paid. Car sent for workshop assessment.');
    return resolveAuction(state,'won',hammer,'LOT '+lotNumber(h.index)+
      ' PAID & TRANSFERRED TO WORKSHOP: £'+(hammer+lot.fee).toLocaleString('en-GB')+
      ' (£'+hammer.toLocaleString('en-GB')+' hammer + £'+lot.fee.toLocaleString('en-GB')+
      ' buyer fee). Any optional paid inspection is separate.');
  }
  function passAuction(state){
    const h=state.auctionHall;
    if(!['catalogue','bidding'].includes(h.phase))
      return fail('stage','This lot is already decided. Move to the next lot.');
    const lot=auctionLot(state);
    if(!lot)return fail('closed','There are no remaining auction lots.');
    if(h.phase==='catalogue')return resolveAuction(state,'passed',0,
      'LOT '+lotNumber(h.index)+' skipped before bidding. No fee charged.');
    // Refusing to match the last rival bid awards the car to the rival only
    // if its actual bid meets reserve. Never invent a higher hammer amount.
    if(h.leader==='player'&&h.currentBid<lot.reserve)
      return resolveAuction(state,'unsold',0,'LOT '+lotNumber(h.index)+
        ' remained unsold below reserve. No sale or buyer fee.');
    if(h.leader==='player')
      return fail('stage','You already hold the winning bid; settle the hammer first.');
    const rivalWins=h.currentBid>=lot.reserve;
    return resolveAuction(state,rivalWins?'lost':'unsold',
      rivalWins?h.currentBid:0,
      rivalWins?'LOT '+lotNumber(h.index)+
        ' SOLD TO RIVAL for £'+h.currentBid.toLocaleString('en-GB')+
        '. You declined to match and pay no fee.':'LOT '+lotNumber(h.index)+
        ' UNSOLD. You withdrew and the last rival bid did not meet the vendor reserve. No fee.');

  }
  function nextAuctionLot(state){
    const h=state.auctionHall;
    if(h.phase!=='result')return fail('stage','Finish or pass this lot before continuing.');
    const length=marketFor(state).auctions.length;
    h.index++;h.currentBid=0;h.playerBid=0;h.rounds=0;h.rivalFolded=false;
    h.feed=[];h.leader='none';h.phase=h.index>=length?'finished':'catalogue';
    return {ok:true,changed:true,message:h.phase==='finished'?
      'Today’s Auction Hall has finished. Review the results or return tomorrow.':
      'LOT '+lotNumber(h.index)+' is on the rostrum. Inspect it before opening the bidding.'};
  }
  function rollAuctionHall(state){
    state.auctionHall=initialAuctionHall(state.day);
  }

  function create(name, messages) {
    const state={
      version:VERSION,name,day:1,cash:STARTING_CASH,capacity:CAPACITY,
