'use strict';
/*
 * Local career persistence. The original browser key and game save schema
 * are deliberately unchanged; this module only adds recovery safeguards.
 */
(() => {
  const KEY = 'the-motor-trade-career-v1';
  const BACKUP_KEY = 'the-motor-trade-career-backup-v1';
  const EXPORT_TYPE = 'the-motor-trade-career-export';
  const EXPORT_FORMAT = 1;
  const MAX_IMPORT_BYTES = 12 * 1024 * 1024;
  let lastSeenRaw = null;
  let activeKey = KEY;
  let activeBackupKey = BACKUP_KEY;
  function setNamespace(userId) {
    if (userId !== null && !/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i.test(userId))
      throw new Error('Invalid account identifier.');
    activeKey = userId === null ? KEY : 'the-motor-trade-account-' + userId.toLowerCase() + '-v1';
    activeBackupKey = userId === null ? BACKUP_KEY : 'the-motor-trade-account-backup-' + userId.toLowerCase() + '-v1';
    lastSeenRaw = null;
  }

  function store() {
    try { return window.localStorage; }
    catch (_) { return null; }
  }

  function decode(raw, normalize) {
    if (typeof raw !== 'string' || !raw) return null;
    try {
      const parsed = JSON.parse(raw);
      let state = parsed;
      if (parsed && typeof parsed === 'object' &&
        Object.prototype.hasOwnProperty.call(parsed, 'type')) {
        if (parsed.type !== EXPORT_TYPE || parsed.format !== EXPORT_FORMAT ||
          !Object.prototype.hasOwnProperty.call(parsed, 'career')) return null;
        state = parsed.career;
      }
      return normalize(state) || null;
    } catch (_) { return null; }
  }

  function status(normalize) {
    const storage = store();
    if (!storage) return {available:false, hasPrimary:false,
      primaryDamaged:false, backupAvailable:false};
    try {
      const raw = storage.getItem(activeKey);
      const backup = storage.getItem(activeBackupKey);
      return {available:true, hasPrimary:raw !== null,
        primaryDamaged:raw !== null && !decode(raw, normalize),
        backupAvailable:!!decode(backup, normalize)};
    } catch (_) {
      return {available:false, hasPrimary:false,
        primaryDamaged:false, backupAvailable:false};
    }
  }

  function load(normalize) {
    const storage = store();
    if (!storage) return {career:null, available:false,
      primaryDamaged:false, backupAvailable:false};
    try {
      const raw = storage.getItem(activeKey);
      lastSeenRaw = raw;
      const career = decode(raw, normalize);
      const backupAvailable = !!decode(storage.getItem(activeBackupKey), normalize);
      return {career, available:true, primaryDamaged:raw !== null && !career,
        backupAvailable, backupOnly:raw === null && backupAvailable};
    } catch (_) {
      return {career:null, available:false,
        primaryDamaged:false, backupAvailable:false};
    }
  }

  function save(career, normalize, options = {}) {
    const storage = store();
    if (!storage) return {ok:false,
      message:'Browser storage is blocked. Export your career to a file before leaving.'};
    let raw;
    try {
      raw = JSON.stringify(career);
      if (!decode(raw, normalize)) return {ok:false,
        message:'Career integrity check failed. Nothing was written. Export your career before leaving.'};
      const previous = storage.getItem(activeKey);
      if (!options.force && previous !== lastSeenRaw && previous !== raw)
        return {ok:false, message:'This career was changed in another tab. No save was overwritten. Export this tab, then reload to choose which career to keep.'};
      // Writing the valid new state FIRST makes a quota/write error harmless:
      // the old primary remains intact. A failed backup never blocks saving.
      if (previous !== raw) storage.setItem(activeKey, raw);
      lastSeenRaw = raw;
      const previousCareer = previous !== raw ? decode(previous, normalize) : null;
      const existingBackup = previousCareer ? decode(storage.getItem(activeBackupKey), normalize) : null;
      // Retain a meaningful restore point: do not replace the previous game
      // day's backup on every same-day inbox read, approval or render.
      // Explicit replacement/import/restore may always back up the old career.
      if (previousCareer && (options.backupPrevious ||
        !existingBackup || previousCareer.day !== career.day)) {
        try { storage.setItem(activeBackupKey, previous); }
        catch (_) { /* Keep the successfully written primary. */ }
      }
      return {ok:true};
    } catch (_) {
      return {ok:false,
        message:'The browser could not save this career (storage unavailable or full). Export a file before leaving.'};
    }
  }

  function recover(normalize) {
    const storage = store();
    if (!storage) return {ok:false, message:'Browser storage is unavailable.'};
    try {
      const career = decode(storage.getItem(activeBackupKey), normalize);
      if (!career) return {ok:false, message:'No valid local backup is available.'};
      const result = save(career, normalize, {force:true, backupPrevious:true});
      return {...result, career:result.ok ? career : null};
    } catch (_) {
      return {ok:false, message:'Unable to read or restore the backup.'};
    }
  }

  function exportText(career, normalize) {
    if (!career || !decode(JSON.stringify(career), normalize))
      throw new Error('This career did not pass the integrity check and cannot be exported as a valid save.');
    return JSON.stringify({
      type:EXPORT_TYPE, format:EXPORT_FORMAT,
      exportedAt:new Date().toISOString(), career
    }, null, 2);
  }

  function importText(text, normalize) {
    if (typeof text !== 'string' || text.length > MAX_IMPORT_BYTES)
      return {ok:false, message:'The selected file is too large or unreadable.'};
    try {
      const file = JSON.parse(text);
      if (!file || typeof file !== 'object' ||
        file.type !== EXPORT_TYPE || file.format !== EXPORT_FORMAT ||
        !Object.prototype.hasOwnProperty.call(file, 'career'))
        return {ok:false, message:'Not a supported The Motor Trade career backup file.'};
      const career = normalize(file.career);
      if (!career) return {ok:false,
        message:'The backup is damaged, incompatible, or fails the cash/stock integrity checks.'};
      return {ok:true, career};
    } catch (_) {
      return {ok:false, message:'Invalid JSON backup. Your current career has not been changed.'};
    }
  }

  window.MotorTradeCareerStorage = Object.freeze({
    KEY, BACKUP_KEY, MAX_IMPORT_BYTES, load, status, save, recover,
    exportText, importText, setNamespace
  });
})();

simulator.js:
'use strict';
/*
 * The Motor Trade — first playable multi-source trading career.
 * All market prices, buyer behaviour and stock are fictional; game only.
 * Single-slot career save with backward-compatible foundation migration.
 */
(() => {
  const E = window.MotorTradeEngine;
  const PV = window.MotorTradePeopleView;
  const MV = window.MotorTradeMonthlyView;
  const EV = window.MotorTradeEventsView;
  const WV = window.MotorTradeWorkshopView;
  const CV = window.MotorTradeCustomersView;
  const AV = window.MotorTradeAuctionHallView;
  const SITE_VIEW = window.MotorTradePremisesView;
  const DV = window.MotorTradeDashboardView;
  const IN = window.MotorTradeInbox;
  const BV = window.MotorTradeBuyingDeskView;
  const SV = window.MotorTradeStockView;
  const FV = window.MotorTradeFinanceView;
  if (!E || !PV || !MV || !EV || !WV || !CV || !SITE_VIEW || !AV || !DV || !IN || !BV || !SV || !FV)
    throw new Error('Customer, workshop and report modules must load before simulator.js');
  const P = E.people;
  const M = E.monthly;
  const D = E.events;
  const W = E.workshop;
  const C = E.customers;
  const SITE = E.premises;
  const VC = window.MotorTradeCards;
  if(!VC)throw new Error('Load vehicle-cards.js before simulator.js');
  const MARKET = window.MotorTradeMarket;
  if(!MARKET)throw new Error('Load vehicle-market.js before simulator.js');
  const SAVES = window.MotorTradeCareerStorage;
  if(!SAVES)throw new Error('Load career-storage.js before simulator.js');
  const ACCOUNT = window.MotorTradeAccountUI;
  const DISPLAY_KEY = 'the-motor-trade-display-v1';
  const STARTING_CASH = 45000; // new staffed career only; old saves retain their own capital
  const CAPACITY = E.CAPACITY;
  const START_DATE_UTC = Date.UTC(2026, 10, 9);
  const MS_PER_DAY = 24 * 60 * 60 * 1000;
  const MAX_DAY = 36500;
  const PAGES = Object.freeze({
    dashboard: 'DASHBOARD',
    inbox: 'INBOX',
    auctions: 'BUYING DESK',
    auctionHall: 'AUCTION HALL',
    stock: 'VEHICLE STOCK',
    workshop: 'WORKSHOP OPERATIONS',
    sales: 'SALES OFFICE',
    finance: 'FINANCES',
    reports: 'MANAGEMENT REPORTS',
    events: 'EVENTS & MEETINGS',
    staff: 'STAFF & RECRUITMENT',
    reputation: 'REPUTATION',
    business: 'MY DEALERSHIP'
  });
  const money = new Intl.NumberFormat('en-GB', {
    style: 'currency', currency: 'GBP', minimumFractionDigits: 0, maximumFractionDigits: 0
  });
  const dateShort = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'UTC', weekday: 'short', day: '2-digit', month: 'short', year: 'numeric'
  });
  const dateLong = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'UTC', day: '2-digit', month: 'long', year: 'numeric'
  });
  const weekdayLong = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'UTC', weekday: 'long'
  });
  const byId = id => document.getElementById(id);
  const all = selector => Array.from(document.querySelectorAll(selector));
  const escapeText = value => String(value).replace(/[&<>"']/g, c => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  })[c]);

  function makeMessage(id, day, from, subject, preview, body, linkPage) {
    return { id, day, from, subject, preview, body, linkPage, read: false };
  }
  function welcomeMessages() {
    return [
      makeMessage(1,1,'BUSINESS SUPPORT','Welcome to the motor trade',
        'Your £45,000 dealership opens with a complete four-person team.',
        'Your dealership starts with £45,000 in cash, four forecourt spaces and one salaried employee in each essential role: sales, buying, preparation and staff supervision. Their wages cost money every game day, so preserve working capital. Visit the Auction Hall for numbered-lot bidding and the Buying Desk for private sellers.\n\nA car needs workshop assessment, timed repairs and a passed final quality check before advertising. Once listed, customer enquiries are not guaranteed: book appointments, arrange test drives, negotiate and complete handover. A part-exchange becomes your next stock vehicle.',
        'auctionHall'),
      makeMessage(2,1,'BUYING DESK','Three ways to find your next car',
        'Auctions, direct sellers and part-exchanges all supply vehicles.',
        'Auctions have competing traders and buyer fees. Direct sellers can reject low offers. Part-exchanges happen when you sell one of your advertised cars and agree an allowance for the customer\'s existing vehicle.\n\nEvery route affects your cash and stock differently. Your first market opportunities are waiting.',
        'auctionHall'),
      makeMessage(3,1,'ACCOUNTS OFFICE','Protect your opening £45,000',
        'Gross margin is different from cash flow.',
        'Every purchase and preparation job costs cash. Customer sales return cash, while part-exchange deals include the incoming vehicle as a separate purchase.\n\nThe Finances page records each transaction. Gross trade margin excludes staff and premises overheads; the management report shows an operating contribution after those charges. VAT, tax, finance and after-sale claims remain unmodelled.',
        'finance')
    ];
  }
  const scheduledMessages = Object.freeze({
    2: () => makeMessage(4,2,'BUYING DESK','Today\'s stock opportunities have refreshed',
      'Private seller opportunities have refreshed.',
      'Auctions run once per week, normally Monday or Tuesday when Monday is Deal Day. Other days are for private sellers and retail trading.',
      'auctionHall'),
    3: () => makeMessage(5,3,'SALES ADVISER','Cash sale or part-exchange?',
      'Both deals can move your stock, but they affect your cash differently.',
      'A cash customer pays the agreed sale price at handover. A part-exchange customer brings a car and pays only the balance after the agreed allowance. You own that incoming car and must prepare it before advertising it.',
      'sales'),
    5: () => makeMessage(6,5,'ACCOUNTS OFFICE','Review your trading margins',
      'Check the ledger for purchases, costs and completed sales.',
      'Your ledger separates auction fees, purchases, preparation bills, cash receipts and part-exchange allowances. Gross trade margin is only an initial game measure and is not net accounting profit.',
      'finance'),
    7: () => makeMessage(7,7,'BUSINESS SUPPORT','Your first week as a trader',
      'Review sales, stock age and cash reserves.',
      'Buying cheap is not enough. The best dealers keep vehicles moving, avoid tying up too much cash and know when to walk away from a risky deal. More management systems will follow this playable trading foundation.',
      'business')
  });

  const display = { showroom: true, motion: true };
  try {
    const savedDisplay = JSON.parse(localStorage.getItem(DISPLAY_KEY) || 'null');
    if (savedDisplay && typeof savedDisplay.showroom === 'boolean' &&
        typeof savedDisplay.motion === 'boolean') {
      display.showroom = savedDisplay.showroom;
      display.motion = savedDisplay.motion;
    }
  } catch (_) { /* Display preferences are optional. */ }
  function saveDisplay() {
    try { localStorage.setItem(DISPLAY_KEY, JSON.stringify(display)); }
    catch (_) { /* Keep settings active for this visit. */ }
  }
  const loadedCareer = SAVES.load(E.normalize);
  let career = loadedCareer.career;
  let saveWarningText = loadedCareer.available ? '' :
    'Browser storage is unavailable. Export a career file before leaving.';
  let saveToolsMessage = '';

  function persistCareer() {
    if (!career) return false;
    const result = SAVES.save(career, E.normalize);
    saveWarningText = result.ok ? '' : result.message;
    if(result.ok || ACCOUNT?.isCloudMode()) ACCOUNT?.notifyCareerSaved(career);
    return result.ok;
  }

  let screen = 'menu'; // The cinematic main menu is the entry point for all careers.
  let currentPage = 'dashboard';
  let selectedMessageId = null;
  let inboxFilter = 'all';
  let eventNotice = '';
  let lastTradeResult = null;
  let expandedReportId = null;
  let auctionPreviewId = null;
  let offerDrafts = {};
  let selectedSellerId = null;
  let selectedStockId = null;
  let stockFilter = 'all';
  let selectedWorkshopId = null;
  let workshopFilter = 'all';
  let selectedSalesId = null;
  let salesFilter = 'all';
  let ledgerFilter = 'all';
  let ledgerExpanded = false;
  let staffDeskMode = null;
  let staffDeskRole = 'all';
  let staffDeskSelectedId = null;
  let selectedMonth = 'current'; // Current-day input, retained while opening a report.

  function gameDate(day) {
    return new Date(START_DATE_UTC + (day - 1) * MS_PER_DAY);
  }
  function unreadCount() {
    return career ? career.messages.filter(m => !m.read).length : 0;
  }
  function bindText(name, value) {
    for (const node of all('[data-bind="' + name + '"]')) node.textContent = value;
  }
  function renderMessageRow(message, compact) {
    const button = document.createElement('button');
    button.type = 'button';
    button.dataset.action = 'read-message';
    button.dataset.id = String(message.id);
    const pending=IN.needsAction(message,career);
    const category=IN.infer(message);
    button.className = (compact ? 'message-preview' : 'inbox-row')+
      (message.read ? '' : ' is-unread')+(pending?' inbox-row-action':'');
    if (!compact) button.setAttribute('aria-pressed', String(message.id === selectedMessageId));
    const stamp = message.day === 1 ? 'DAY 01' : 'DAY ' + String(message.day).padStart(2, '0');
    button.innerHTML =
      '<span class="message-icon" aria-hidden="true">✉</span>' +
      '<span class="message-copy">' +
        '<span class="message-from"><span>' + escapeText(message.from) + '</span><time>' + stamp + '</time></span>' +
        '<span class="message-title">' + escapeText(message.subject) + '</span>' +
        (!compact?'<span class="inbox-message-tags"><b>'+escapeText(IN.labels[category]||category)+
          '</b>'+(pending?'<b class="inbox-tag-action">APPROVAL REQUIRED</b>':'')+
