      (filter==='action'&&counts.action?' · '+counts.action:'')+'</button>').join('');
    const detail=byId('inbox-detail');
    if(selectedMessageId===null||!ordered.some(m=>m.id===selectedMessageId))
      selectedMessageId=ordered[0]?.id??null;
