          const key=button.dataset.kind+':'+button.dataset.id;
          if(button.dataset.kind==='auction'&&
             E.auctionLot(career)?.id!==button.dataset.id)
            auctionPreviewId=button.dataset.id;
          expandedReportId=expandedReportId===key?null:key;
